/* Restores the existing automatic AI fallback search behavior after the fine-arts-only detail patch. */
(() => {
  'use strict';
  if (document.querySelector('#aiSearchRun')) return;
  const clean=v=>String(v||'').replace(/\s+/g,' ').trim();
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const safeUrl=v=>{try{const u=new URL(String(v||''));return /^https?:$/.test(u.protocol)?u.href:'';}catch(_){return'';}};
  const allUnits=()=>[...(window.RESEARCH_UNITS||[]),...(window.RESEARCH_UNIT_SUPPLEMENTS||[])];
  const enrichment=x=>(window.PRECOMPUTED_ENRICHMENT||{})[x.id]||{};
  const input=document.querySelector('#q'),status=document.querySelector('#aiStatus'),results=document.querySelector('#results'),sort=document.querySelector('#sort'),aiButton=document.querySelector('#aiRecommend');
  const aiOption=sort&&[...sort.options].find(o=>o.value==='ai');if(aiOption)aiOption.remove();if(aiButton)aiButton.remove();
  document.querySelector('.ai-actions')?.classList.add('automatic-ai-status');
  if(status)status.textContent='일반 검색 결과는 입력과 동시에 표시됩니다. 일치 결과가 없을 때만 Enter 또는 AI 유사 검색을 눌러 추천을 요청할 수 있습니다.';
  const searchButton=document.createElement('button');searchButton.id='aiSearchRun';searchButton.type='button';searchButton.className='ai-search-run';searchButton.setAttribute('aria-label','AI 유사 검색 실행');searchButton.innerHTML='<span aria-hidden="true">→</span>';
  if(input?.parentElement){const row=document.createElement('div');row.className='ai-search-row';input.parentElement.insertBefore(row,input);row.append(input,searchButton);}
  const style=document.createElement('style');style.textContent='.ai-search-row{position:relative;display:block}.ai-search-row #q{box-sizing:border-box;padding-right:58px}.ai-search-run{position:absolute;right:8px;top:50%;transform:translateY(-50%);min-height:36px;width:38px;padding:0;border:0;border-radius:9px;background:#135fbe;color:#fff;font:700 .78rem system-ui,-apple-system,"Noto Sans KR",sans-serif;cursor:pointer;white-space:nowrap}.ai-search-run:disabled{opacity:.6;cursor:wait}@media(max-width:430px){.ai-search-row #q{padding-right:52px}.ai-search-run{right:6px;width:36px;padding:0;font-size:1rem}}';document.head.appendChild(style);
  let activeKey='',lastShownKey='';
  function scoreCandidate(unit,query){const e=enrichment(unit),terms=[unit.name,unit.title,unit.labs,unit.fields,unit.keywords,e.research_summary,...(e.research_topics||[]),...(e.recommendation_keywords||[])].map(v=>clean(v).toLowerCase()).join(' '),tokens=query.toLowerCase().split(/[\s,;]+/).filter(Boolean);let score=tokens.reduce((s,t)=>s+(terms.includes(t)?Math.min(20,t.length*2):0),0),compact=terms.replace(/\s/g,'');for(const token of tokens){const t=token.replace(/\s/g,'');if(t.length>=2&&compact.includes(t))score+=t.length;}return score;}
  function cacheKey(query,college,department){const raw=[window.AUTOMATION_META?.updated_at||'static',query.toLowerCase(),college,department].join('|');let hash=2166136261;for(let i=0;i<raw.length;i++)hash=Math.imul(hash^raw.charCodeAt(i),16777619);return'snu-lab-no-match-ai-v2:'+(hash>>>0).toString(16);}
  function renderAi(items){results.innerHTML=items.map(item=>{const x=item.unit,photo=safeUrl(String(x.photo||'').split(/[;,|]/)[0]),avatar=photo?'<span class="avatar avatar-stack"><img class="avatar-photo loaded" src="'+esc(photo)+'" alt="'+esc(x.name)+' 교수 사진" loading="lazy"><span class="avatar-initial" hidden>'+esc(String(x.name||'?')[0])+'</span></span>':'<span class="avatar fallback">'+esc(String(x.name||'?')[0])+'</span>',lab=clean(String(x.labs||x.title||'연구그룹').split(/[;|]/)[0]),affiliation=typeof window.SnuAffiliationLabel==='function'?window.SnuAffiliationLabel(x):[x.college,x.department].filter(Boolean).join(' ');return'<button class="card" data-i="'+allUnits().indexOf(x)+'">'+avatar+'<span class="card-copy"><h2>'+esc(x.name+' 교수 / '+lab)+'</h2><span class="meta">'+esc([affiliation,x.rank].filter(Boolean).join(' · '))+'</span><span class="ai-reason"><strong>AI 유사 추천 이유</strong>'+esc(item.reason)+'</span></span></button>';}).join('')||'<p class="empty">AI가 공식 저장 정보에서 적합한 후보를 찾지 못했습니다.</p>';}
  async function runAiFallback(){const query=clean(input?.value);if(!query){input?.focus();if(status)status.textContent='먼저 검색어를 입력해 주세요.';return;}if(document.querySelectorAll('#results .card').length){if(status)status.textContent='직접 일치하는 결과를 실시간으로 표시하고 있습니다. AI 유사 검색은 일치 결과가 없을 때 사용합니다.';return;}const college=document.querySelector('#college')?.value||'',department=document.querySelector('#department')?.value||'',key=cacheKey(query,college,department);if(activeKey===key||lastShownKey===key)return;if(!window.SnuAccount?.isLoggedIn?.()){if(status)status.textContent='일치하는 결과가 없습니다. AI 유사 검색을 사용하려면 로그인해 주세요.';window.SnuAccount?.open?.();return;}const pool=allUnits().filter(x=>(!college||x.college===college)&&(!department||x.department===department)),candidates=pool.map(x=>({x,score:scoreCandidate(x,query)})).sort((a,b)=>b.score-a.score||String(a.x.name).localeCompare(String(b.x.name),'ko')).slice(0,160).map(({x})=>{const e=enrichment(x);return{id:x.id,professor:x.name,lab:x.labs||x.title,college:x.college,department:x.department,research_summary:clean(e.research_summary||x.fields).slice(0,500),topics:(e.research_topics||[]).slice(0,12),keywords:(e.recommendation_keywords||[]).slice(0,18)};}).filter(x=>x.research_summary||x.lab);if(!candidates.length)return;activeKey=key;searchButton.disabled=true;searchButton.textContent='검색 중…';try{const cached=JSON.parse(localStorage.getItem(key)||'null');let recommendations=cached?.recommendations;if(!recommendations){if(status)status.textContent='일치 결과가 없어 저장된 공식 연구 정보를 바탕으로 AI가 유사한 연구 단위를 찾고 있습니다…';const response=await window.SnuAccount.callGemini({systemInstruction:{parts:[{text:'서울대학교 연구실 추천자. 검색어와 후보 데이터만 사용한다. 후보에 없는 ID를 만들지 않는다. 검색어의 의미를 해석해 가장 가까운 후보만 한국어로 짧게 추천하고, 근거 없는 사실은 쓰지 않는다.'}]},contents:[{role:'user',parts:[{text:JSON.stringify({task:'검색 결과가 0개일 때 가장 가까운 서울대학교 교수·연구실 최대 12개 추천',search_query:query,candidates})}]}],generationConfig:{temperature:.15,maxOutputTokens:2600,responseMimeType:'application/json',responseSchema:{type:'OBJECT',properties:{recommendations:{type:'ARRAY',items:{type:'OBJECT',properties:{id:{type:'STRING'},reason:{type:'STRING'}},required:['id','reason']}}},required:['recommendations']}}});const raw=response.payload?.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('')||'{}';recommendations=(JSON.parse(raw.replace(/^```json\s*/i,'').replace(/\s*```$/,'')).recommendations||[]).filter(item=>allUnits().some(x=>x.id===item.id)).slice(0,12);localStorage.setItem(key,JSON.stringify({saved_at:new Date().toISOString(),recommendations}));}const byId=new Map(allUnits().map(x=>[x.id,x]));renderAi(recommendations.map(item=>({unit:byId.get(item.id),reason:clean(item.reason)})).filter(item=>item.unit));if(status)status.textContent='직접 일치 결과는 없지만, 저장된 공식 정보 기준으로 AI가 유사한 연구 단위를 추천했습니다.';lastShownKey=key;}catch(error){const message=String(error?.message||'');if(status)status.textContent=/(^|\D)401(\D|$)|authentication|unauthorized/i.test(message)?'AI 서버 인증 오류입니다. 앱 검색 문제가 아니라 Gemini 프록시 배포·서버 키 설정을 점검해야 합니다.':'AI 유사 추천을 완료하지 못했습니다: '+(message||'알 수 없는 오류');}finally{activeKey='';searchButton.disabled=false;searchButton.innerHTML='<span aria-hidden="true">→</span>';}}
  function simplifyDetailLinks(){const dialog=document.querySelector('#detail');if(!dialog?.open)return;dialog.querySelectorAll('.research-section .ai-sources').forEach(n=>n.remove());dialog.querySelectorAll('.actions a').forEach(link=>{if(clean(link.textContent)!=='연구실 홈페이지')link.remove();});}
  new MutationObserver(simplifyDetailLinks).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['open']});
  searchButton.addEventListener('click',runAiFallback);input?.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();runAiFallback();}});
})();
